contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint balAfterDeposit = address(c).balance;

        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstReverted = true; } else { firstReverted = false; }

        uint balAfterFirstWithdraw = address(c).balance;

        bool secondReverted;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { secondReverted = true; } else { secondReverted = false; }

        uint balAfterSecondWithdraw = address(c).balance;

        assert(
            !firstReverted &&
            balAfterDeposit == balBefore + amount &&
            !secondReverted &&
            balAfterSecondWithdraw == balAfterFirstWithdraw &&
            balAfterFirstWithdraw == balBefore
        );
    }

    receive() external payable {}
}

