pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint balBefore = address(c).balance;
        try c.deposit{value: amount}() {} catch { return; }
        uint balAfterDeposit = address(c).balance;
        bool firstReverted;
        try c.withdrawAll() { firstReverted = false; } catch { firstReverted = true; }
        uint balAfterFirstWithdraw = address(c).balance;
        bool secondReverted;
        try c.withdrawAll() { secondReverted = false; } catch { secondReverted = true; }
        uint balAfterSecondWithdraw = address(c).balance;
        assertTrue(!firstReverted &&
            balAfterDeposit == balBefore + amount &&
            !secondReverted &&
            balAfterSecondWithdraw == balAfterFirstWithdraw &&
            balAfterFirstWithdraw == balBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
